#!/usr/bin/env python3
from pathlib import Path

p=Path('live_server/v4_engine.py')
s=p.read_text()

old="""    def refresh_usa_tracker(self,db):\n        syms=self.tracked_symbols('USA'); fmap={r['symbol']:r for r in self.finder['USA']['rows']}; pmap={p['symbol']:p for p in self.store.positions('USA')}; qmap={q.get('symbol'):q for q in db.quotes()}; rows=[]\n        for sym in syms:rows.append(self._usa_row(sym,db.ticks(sym,40000),multi_timeframe_signal(sym,db.ticks(sym,40000),db.quotes()),qmap,fmap.get(sym),pmap.get(sym)))\n        rows.sort(key=_tracker_sort_key); self._finalize('USA',rows); return self.tracker['USA']\n"""

new="""    def refresh_usa_tracker(self,db):\n        # V97: paper Williams must evaluate Finder names independently of real V4 positions.\n        # Keep the production tracker behavior intact; only enrich each row with paper-only Williams fields.\n        syms=self.tracked_symbols('USA'); fmap={r['symbol']:r for r in self.finder['USA']['rows']}; pmap={p['symbol']:p for p in self.store.positions('USA')}; qmap={q.get('symbol'):q for q in db.quotes()}; rows=[]\n        for sym in syms:\n            ticks=db.ticks(sym,40000)\n            row=self._usa_row(sym,ticks,multi_timeframe_signal(sym,ticks,db.quotes()),qmap,fmap.get(sym),pmap.get(sym))\n            try:\n                row.update(self._williams_usa_paper_fields(sym,db,row,fmap.get(sym)))\n            except Exception as e:\n                row.update({'williams_entry':False,'williams_signal_entry':False,'williams_struct_state':None,'williams_support':None,'williams_support_updates':None,'williams_exit_ready':False,'williams_error':f'{type(e).__name__}: {e}'[:240]})\n            rows.append(row)\n        rows.sort(key=_tracker_sort_key); self._finalize('USA',rows); return self.tracker['USA']\n\n    def _williams_usa_paper_fields(self,sym,db,row,finder=None):\n        \"\"\"Paper-only USA adapter for the frozen Williams entry + STRUCT0 exit.\n\n        Entry semantics are the existing williams_live_evaluate_v23 trigger:\n        day_open + 0.5*(prior-day high-low), RSI2>50, Finder rank<=20.\n        Exit semantics are the frozen causal higher-low STRUCT0 helper.\n        No real broker order is ever called here.\n        \"\"\"\n        out={\n            'williams_entry':False,'williams_signal_entry':False,\n            'williams_struct_state':None,'williams_support':None,\n            'williams_support_updates':None,'williams_exit_ready':False,\n            'williams_trigger':None,'williams_rsi2':None,'williams_stage':'WAIT_DATA',\n            'williams_orders_enabled':False,'williams_error':None,\n        }\n        if str(row.get('session') or '').upper()!='REGULAR':\n            out['williams_stage']='SESSION_NOT_REGULAR'; return out\n        if not (row.get('data_integrity') or {}).get('valid'):\n            out['williams_stage']='DATA_INVALID'; return out\n\n        ticks=db.ticks(sym,40000)\n        b1=ticks_to_bars(ticks,1)\n        if b1 is None or len(b1)<16:\n            out['williams_stage']='INSUFFICIENT_1M'; return out\n        closes=[_f(x) for x in pd.to_numeric(b1['close'],errors='coerce').dropna().tolist()]\n        if len(closes)<16:\n            out['williams_stage']='INSUFFICIENT_CLOSES'; return out\n\n        # Existing paper position: evaluate frozen STRUCT0 only.\n        ppos=next((x for x in self.paper.account('USA').get('positions',[]) if str(x.get('symbol') or '').upper()==str(sym).upper()),None)\n        if ppos:\n            st=self._williams_structure_state(b1,entry_price=_f(ppos.get('entry_fill_price') or ppos.get('entry_price')))\n            out['williams_struct_state']=st.get('state')\n            out['williams_support']=st.get('support')\n            out['williams_support_updates']=st.get('support_updates')\n            out['williams_exit_ready']=bool(st.get('break'))\n            out['williams_stage']='POSITION_'+str(st.get('state') or 'HOLD')\n            return out\n\n        # Prior regular-session OHLC from the historical 1m store.\n        et=datetime.now(timezone.utc).astimezone(ZoneInfo('America/New_York'))\n        today=et.strftime('%Y%m%d')\n        with self.store._c() as c:\n            prev=c.execute(\n                \"\"\"SELECT trade_date,MAX(high) ph,MIN(low) pl\n                   FROM historical_minute_bars\n                   WHERE symbol=? AND interval_min=1 AND trade_date<? AND session='REGULAR'\n                   GROUP BY trade_date ORDER BY trade_date DESC LIMIT 1\"\"\",\n                (str(sym).upper(),today)\n            ).fetchone()\n        if not prev or _f(prev['ph'])<=0 or _f(prev['pl'])<=0:\n            out['williams_stage']='NO_PREV_DAY'; return out\n\n        day_open=_f(b1.iloc[0]['open'])\n        prev_price=_f(b1.iloc[-2]['close']); cur_price=_f(b1.iloc[-1]['close'])\n        if day_open<=0 or prev_price<=0 or cur_price<=0:\n            out['williams_stage']='BAD_PRICE_INPUT'; return out\n        rank=(finder or {}).get('rank') or row.get('finder_rank')\n        ev=williams_live_evaluate_v23(\n            sym,_f(prev['ph']),_f(prev['pl']),day_open,prev_price,cur_price,closes[-120:],finder_rank=rank\n        )\n        trig=day_open+0.5*(_f(prev['ph'])-_f(prev['pl']))\n        out['williams_trigger']=round(trig,6)\n        out['williams_rsi2']=ev.get('rsi2') if isinstance(ev,dict) else None\n        out['williams_stage']=(ev.get('stage') if isinstance(ev,dict) else None) or 'EVALUATED'\n        sig=bool((ev or {}).get('signal') or (ev or {}).get('entry') or (ev or {}).get('signal_entry') or (ev or {}).get('williams_entry'))\n        out['williams_entry']=sig\n        out['williams_signal_entry']=sig\n        return out\n"""

if '_williams_usa_paper_fields' in s:
    print('ALREADY_PATCHED live_server/v4_engine.py')
elif old not in s:
    raise SystemExit('PATCH_TARGET_NOT_FOUND: refresh_usa_tracker signature/body changed')
else:
    s=s.replace(old,new,1)
    p.write_text(s)
    print('PATCHED live_server/v4_engine.py')

print('ADDED=_williams_usa_paper_fields')
print('ENTRY=frozen Williams V23 trigger, paper-only')
print('EXIT=frozen STRUCT0 support break, paper-only')
print('REAL_BROKER_ORDERS=NO')
